problems.question:
[考试原题]

Consider the following class implementations. 
```python
class A:
    def __init__(self, count: int, n: int, is_sub_class: bool) -> None:
        self.count = count
        self.n = n
        self.some = None
        if n > 1 and not is_sub_class:
            self.some = A(self.count + 1, self.n - 1, is_sub_class)

    def mystery_method(self) -> int:
        if self.some is not None:
            return self.n + self.some.mystery_method()
        return self.n

class B(A):
    def __init__(self, n: int) -> None:
        A.__init__(self, 0, n, True)

    def mystery_method(self) -> int:
        return (self.count * (self.count + 1)) // 2
if __name__ == '__main__':
    some = A(0, 3, False) # Line 1
    some_sub = B(2) # Line 2
    print(some.mystery_method()) # Line 3
    print(some_sub.mystery_method()) # Line 4
    print(A.mystery_method(some_sub)) # Line 5
```

Draw a diagram that shows the state of memory after the second line of the main function (highlighted in comments by Line 2) is executed.

