import unittest

class TestSafeBinaryOpPublic(unittest.TestCase):
    """Public test cases - 学生可见的测试"""
    def test_int_add(self):
        self.assertEqual(safe_binary_op(10, 5, '+'), 15)

    def test_float_mul(self):
        self.assertEqual(safe_binary_op(2.0, 3.5, '*'), 7.0)

    def test_str_concat(self):
        self.assertEqual(safe_binary_op('foo', 'bar', '+'), 'foobar')

    def test_str_repeat(self):
        self.assertEqual(safe_binary_op('x', 4, '*'), 'xxxx')

    def test_invalid_op(self):
        with self.assertRaises(TypeError):
            safe_binary_op(1, 2, '-')

