import unittest

class TestSafeBinaryOpSecret(unittest.TestCase):
    """Secret test cases - 学生不可见的测试"""
    def test_mixed_int_float_add_not_allowed(self):
        # mixing int and float for '+' is not allowed by exact type rules
        with self.assertRaises(TypeError):
            safe_binary_op(1, 2.0, '+')

    def test_bool_and_int_rejected(self):
        # bool is subclass of int, but type(True) != type(1), so should be rejected
        with self.assertRaises(TypeError):
            safe_binary_op(True, 1, '+')

    def test_string_times_float_rejected(self):
        with self.assertRaises(TypeError):
            safe_binary_op('a', 2.0, '*')

    def test_int_times_string_commutative(self):
        # ensure int * string works as well as string * int
        self.assertEqual(safe_binary_op(3, 'ab', '*'), 'ababab')

    def test_two_floats_add_rejected_if_rule_missing(self):
        # ensure '+' for two floats is allowed (sanity check)
        self.assertEqual(safe_binary_op(1.5, 2.25, '+'), 3.75)

