class TestEvalRPNSecret(unittest.TestCase):
    """Secret test cases - 学生不可见的测试"""
    def test_div_trunc_towards_zero(self):
        """除法结果向零截断: 7 / -3 -> -2, -7 / 3 -> -2"""
        self.assertEqual(eval_rpn(["7","-3","/"]), -2)
        self.assertEqual(eval_rpn(["-7","3","/"]), -2)

    def test_mixed_negative(self):
        """包含负数和乘加混合运算"""
        self.assertEqual(eval_rpn(["-2","3","*","5","+"]), -1)

    def test_long_example(self):
        """题目示例的复杂表达式"""
        self.assertEqual(eval_rpn(["10","6","9","3","+","-11","*","/","*","17","+","5","+"]), 22)

    def test_complex(self):
        """经典 RPN 示例: (5 + ((1 + 2) * 4)) - 3 == 14"""
        self.assertEqual(eval_rpn(["5","1","2","+","4","*","+","3","-"]), 14)

