```python
from typing import Dict
def bumbly(d: Dict) -> int: 
    try:
        spot = mia(d) 
        return d [spot]
    except KeyError: 
        print('something went wrong') 
        return -1
def mia (d: Dict) -> int:
    try:
        place = chirly(d) 
        return d[place]
    except KeyError:
        print ('something went wrong') 
        return -1
def chirly(d: Dict) -> int: 
    try:
        return sum(d.values()) 
    except KeyError:
        print ('something went wrong') 
        return -1

