from solution import TreeNode, deep_copy_tree

def structurally_equal(a: TreeNode, b: TreeNode) -> bool:
    if a is None or b is None:
        return a is None and b is None
    if a.val != b.val:
        return False
    if len(a.children) != len(b.children):
        return False
    for ca, cb in zip(a.children, b.children):
        if not structurally_equal(ca, cb):
            return False
    return True

def all_nodes_distinct(a: TreeNode, b: TreeNode) -> bool:
    if a is None or b is None:
        return a is None and b is None
    if a is b:
        return False
    for ca, cb in zip(a.children, b.children):
        if not all_nodes_distinct(ca, cb):
            return False
    return True

class TestDeepCopyTreePublic(unittest.TestCase):
    def test_empty(self):
        self.assertIsNone(deep_copy_tree(None))

    def test_single_node(self):
        root = TreeNode(1)
        cp = deep_copy_tree(root)
        self.assertIsNot(root, cp)
        self.assertEqual(cp.val, 1)
        self.assertEqual(len(cp.children), 0)

    def test_structure_and_identity(self):
        # build tree: 1 -> [2, 3 -> [4]]
        n4 = TreeNode(4)
        n3 = TreeNode(3, [n4])
        n2 = TreeNode(2)
        root = TreeNode(1, [n2, n3])

