        self.assertTrue(structurally_equal(root, cp))
        self.assertTrue(all_nodes_distinct(root, cp))

    def test_mutation_independence(self):
        # build tree: 1 -> [2, 3]
        n2 = TreeNode(2)
        n3 = TreeNode(3)
        root = TreeNode(1, [n2, n3])

        cp = deep_copy_tree(root)
        # mutate copy
        cp.children[0].val = 99
        self.assertEqual(root.children[0].val, 2)

        # mutate original
        root.children.append(TreeNode(8))
        self.assertEqual(len(cp.children), 2)

if __name__ == '__main__':
    unittest.main()

