import unittest
from solution import TreeNode, deep_copy_tree

# helper functions reused from public tests

def structurally_equal(a: TreeNode, b: TreeNode) -> bool:
    if a is None or b is None:
        return a is None and b is None
    if a.val != b.val:
        return False
    if len(a.children) != len(b.children):
        return False
    for ca, cb in zip(a.children, b.children):
        if not structurally_equal(ca, cb):
            return False
    return True

def all_nodes_distinct(a: TreeNode, b: TreeNode) -> bool:
    if a is None or b is None:
        return a is None and b is None
    if a is b:
        return False
    for ca, cb in zip(a.children, b.children):
        if not all_nodes_distinct(ca, cb):
            return False
    return True

class TestDeepCopyTreeSecret(unittest.TestCase):
    def build_balanced(self, depth, breadth, start=1):
        # build a balanced tree of given depth and breadth, values increasing
        cnt = start
        def build(d):
            nonlocal cnt
            node = TreeNode(cnt)
            cnt += 1
            if d > 0:
                node.children = [build(d-1) for _ in range(breadth)]
            return node
        return build(depth)

    def test_deeper_tree_and_mutation(self):
