class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

def insert(root, value):
    if root is None:
        return Node(value)
    current = root
    while True:
        if value < current.key:
            if current.left is None:
                current.left = Node(value)
                break
            else:
                current = current.left
        else:
            if current.right is None:
                current.right = Node(value)
                break
            else:
                current = current.right
    return root

